"""Readable numerical appendix from completed results, no selection or fitting."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def load(p):return json.loads((ROOT/p).read_text(encoding='utf8'))
def main():
 f=load('results/FINAL_ANALYSIS.json');v=load('results/validation_analysis.json');lock=load('configs/FINAL_LOCK.json');unc=load('results/SIGNAL_UNCERTAINTY.json')
 out=['# Statistical appendix','','These are the frozen analyses and clearly labeled secondary diagnostics. Final outcomes do not change the selected policy. Primary accuracy is acc_norm.','', '## Validation and training events','', '| Training action vs Adaptive | Beneficial | Harmful | Neutral |','|---|---:|---:|---:|']
 for a,x in v['events']['by_action'].items():out.append(f"| {a} | {x['positive']} | {x['negative']} | {x['neutral']} |")
 out+=['','Events refer to question-action pairs; several actions on one question are not independent questions. Separate action outputs are fitted jointly without treating the outputs as independent test observations.','', '| Validation policy | Correct /800 | Corrections | Degradations | Net | Delta pp [95% CI] | Holm p |','|---|---:|---:|---:|---:|---|---:|']
 for k,x in v['summary'].items():out.append(f"| {k} | {x['correct']} | {x['corrections']} | {x['degradations']} | {x['net']:+d} | {x['delta_pp']:+.3f} [{x['ci95_pp'][0]:.3f}, {x['ci95_pp'][1]:.3f}] | {v['adjusted_p'].get(k,'NA')} |")
 out+=['',f"Selected: `{lock['selected_policy']}`. {lock['reason']}."]
 for task,r in f['reports'].items():
  out+=['',f'## {task}: paired accuracy','','All policies below are compared against Adaptive on the same questions. Only the locked policy has confirmatory status; the others remain diagnostics.','', '| Policy | Correct | Accuracy % | Corrections | Degradations | Net | Delta pp [95% CI] | Exact McNemar p |','|---|---:|---:|---:|---:|---:|---|---:|']
  for k,x in r['summary'].items():out.append(f"| {k} | {x['correct']} | {x['accuracy_percent']:.3f} | {x['corrections']} | {x['degradations']} | {x['net']:+d} | {x['delta_pp']:+.3f} [{x['ci95_pp'][0]:.3f}, {x['ci95_pp'][1]:.3f}] | {x['mcnemar_p']:.6g} |")
  out+=['','### Retaining corrections and avoiding harm','','The reference sets below are the beneficial and harmful changes made by Adaptive relative to original Ouro. The selected controller can also change other questions; those effects are captured by the paired table.','', '| Policy | Benefit retained | Benefit rejected | Harm avoided | Harm accepted |','|---|---:|---:|---:|---:|']
  for k,x in r['correction_accounting'].items():out.append(f"| {k} | {x['beneficial_retained']} | {x['beneficial_rejected']} | {x['harmful_avoided']} | {x['harmful_accepted']} |")
  out+=['','### Action-rate-matched random controls','','Permute the observed action assignments across questions, preserving every action count; 1000 shuffles, seed2021. This controls action rates, not conditional question difficulty. The following p values are descriptive and unadjusted.','', '| Policy | Observed correct | Random mean | Random 95% interval | Randomization p (random >= observed) |','|---|---:|---:|---|---:|']
  for k,x in r['random_controls'].items():out.append(f"| {k} | {x['observed_correct']} | {x['random_correct_mean']:.2f} | {x['random_correct_interval95']} | {x['randomization_p_ge']:.4f} |")
  out+=['','### Update-value discrimination','','Only beneficial and harmful (nonzero) events enter AUC; neutral events were retained in training. Confidence-quartile AUC and individual head AUC are in FINAL_ANALYSIS.json. Paired AUC-difference intervals below are exploratory and unadjusted. An interval covering zero does not establish additional information beyond the control head.','', '| Action | Positive / negative | Head contrast | Delta AUC [95% CI] |','|---|---|---|---|']
  for a,x in unc['datasets'][task].items():
   for k,d in x['paired_auc_differences'].items():out.append(f"| {a} | {x['positive']} / {x['negative']} | {k} | {d['delta_auc']:+.3f} [{d['ci95'][0]:.3f}, {d['ci95'][1]:.3f}] |")
  out+=['','### Head overhead','','CPU wall time includes feature construction, array conversion, scaling and matrix multiply for one head. It excludes backbone passes, which are measured separately.','', '| Head | Parameters | CPU ms/question |','|---|---:|---:|']
  for k,x in r['head_diagnostics'].items():out.append(f"| {k} | {f['training_head_parameters'][k]} | {x['_inference']['milliseconds_per_question']:.4f} |")
 out+=['','## Hypothesis interpretation','','* **H0:** Failure of the locked gate is compatible with insufficient accessible signal under this representation and sample size; it does not prove that all update-value signals are unidentifiable.','* **H1:** Fixed-sign question-loss, geometry, token-support and formatting policies are falsifiable by their held-out paired accuracy. A favorable post-test diagnostic cannot retroactively pass the validation gate.','* **H2:** The six frozen ridge heads test a bounded family and one training size. Positive AUC alone is insufficient; usable superiority requires the locked controller to pass the paired accuracy gates.','* **H3:** Removing supplied SciQ evidence tests its contribution to this task. The format intervention adds no independent facts. Neither establishes that extra evidence is necessary for every successful frozen controller; H3 remains only partially tested.','']
 (ROOT/'STATISTICAL_APPENDIX.md').write_text('\n'.join(out),encoding='utf8');print('Wrote STATISTICAL_APPENDIX.md')
if __name__=='__main__':main()
